104	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor
105	// slice at `off` within the flat [m|v|extra] layout. Per-TENSOR fields (the
106	// NeuralGrok psi MLP weights) and all scalars pass through unchanged.
107	template <OptId Opt>
108	__device__ __forceinline__ FusedOptState
109	rebase_state(const FusedOptState& s, int64_t off) {
110	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
111	    if (t.exp_avg)    t.exp_avg    += off;
112	    if (t.exp_avg_sq) t.exp_avg_sq += off;
113	    if (t.ema)        t.ema        += off;
114	    if (t.sam_dir)    t.sam_dir    += off;
115	    if (t.s_track)    t.s_track    += off;
116	    if (t.mu)         t.mu         += off;
117	    if (t.orth)       t.orth       += off;
118	    if (t.smart_grad) t.smart_grad += off;
119	    return t;
120	}
121	
122	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
123	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
124	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
125	//
126	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
127	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
128	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
129	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
130	// total == kDecTotalElems == 422755.
131	
132	struct DecoderTokenCtx {
133	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
134	    const int* targets;  // [B]       int32 target ids
135	    int        B;        // batch size (full-batch in the race ≈ 4191)
136	    float*     workspace; // grad partials + loss partials + reduced loss
137	    float*     loss_out;  // device float the kernel writes the mean loss into
138	};
139	
140	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
141	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
142	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
143	//    the launcher is unchanged). ────────────────────────────────────────────────
144	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
145	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
146	// the reduce + optimizer phases read them directly. This also lets the host side
147	// (dispatch.cpp) avoid building any layout tensors.
148	template <OptId Opt>
149	__global__ void __launch_bounds__(256)
150	fused_decoder_megakernel(PersistentContext ctx,
151	                         float* __restrict__ params,
152	                         DecoderTokenCtx tok,
153	                         float* __restrict__ grad,        // reduced grad [total]
154	                         float lr, int step, FusedOptState st) {
155	    __shared__ DecSampleSmem sm;
156	    GridBarrier bar = ctx.barrier();
157	    const int cta = blockIdx.x;
158	    const int nCTA = (int)ctx.n_ctas;
159	    const int64_t total = kDecTotalElems;
160	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
161	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
162	
163	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
164	    const int wg = threadIdx.x / 128;
165	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
166	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
167	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
168	
169	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
170	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
171	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
172	    bar.sync();   // B0
173	
174	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
175	    DecWeights w = dec_bind(params);
176	    DecGrad g = dec_bind_grad(my_partial);
177	    // Even split with remainder to the low CTAs (contiguous, deterministic).
178	    const int B = tok.B;
179	    const int base = B / nCTA, rem = B % nCTA;
180	    const int b0 = cta * base + (cta < rem ? cta : rem);
181	    const int cnt = base + (cta < rem ? 1 : 0);
182	    const int b1 = b0 + cnt;
183	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
184	    __shared__ int tgt_s;
185	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
186	    for (int b = b0; b < b1; ++b) {
187	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
188	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
189	        __syncthreads();
190	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
191	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
192	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
193	        __syncthreads();   // sample boundary: all grad writes done before reuse
194	    }
195	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
196	    bar.sync();   // B1: all CTA partials + loss slots complete
197	
198	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
199	    //    (one task = one parameter tensor; sum its elements across CTAs in
200	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
201	    //    the result is deterministic regardless of which CTA grabs the task. ────
202	    {
203	        __shared__ int task_slot;
204	        TaskQueue q = ctx.queue();
205	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
206	             t = q.next_block(&task_slot)) {
207	            const int n = kDecSizes[t];
208	            const int64_t off = (int64_t)kDecOffsets[t];
209	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
210	                float acc = 0.0f;
211	                // ascending CTA index → fixed fp32 summation order (deterministic).
212	                for (int c = 0; c < nCTA; ++c)
213	                    acc += tok.workspace[(int64_t)c * total + off + i];
214	                grad[off + i] = acc;
215	            }
216	        }
217	    }
218	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
219	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
220	    if (cta == 0 && threadIdx.x == 0) {
221	        double s = 0.0;
222	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
223	        float mean = (float)(s / (double)B);
224	        *tok.loss_out = mean;
225	    }
226	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
227	
228	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
229	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
230	    st.lr = lr;
231	    {
232	        __shared__ int task_slot;
233	        TaskQueue q = ctx.queue();
234	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
235	             t = q.next_block(&task_slot)) {
236	            const int n = kDecSizes[t];
237	            const int64_t off = (int64_t)kDecOffsets[t];
238	            const FusedOptState ts = rebase_state<Opt>(st, off);
239	            float* __restrict__ p = params + off;
240	            const float* __restrict__ gg = grad + off;
241	            for (int i = threadIdx.x; i < n; i += blockDim.x)
242	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
243	        }
244	    }
245	}
246	
247	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
248	//    Mirrors launch_fused_megakernel's hang-freedom contract: occupancy≥1 or
249	//    refuse (the GridBarrier rendezvous of n_ctas CTAs can never complete if a
250	//    CTA can't be placed). Zeroes the barrier+task counters per launch. ─────────
251	template <OptId Opt>
252	cudaError_t launch_fused_decoder_megakernel(
253	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
254	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
255	    int dev = 0;
256	    cudaError_t err = cudaGetDevice(&dev);
257	    if (err != cudaSuccess) return err;
258	    int n_sms = 0;
259	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
260	    if (err != cudaSuccess) return err;
261	
262	    int occ = 0;
263	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
264	        &occ, (const void*)&fused_decoder_megakernel<Opt>, 256,
265	        /*dynamicSMemBytes=*/0);
266	    if (err != cudaSuccess) return err;
267	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
268	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
269	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
270	    assert(occ >= 1 &&
271	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
272	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
273	           "reduce footprint or fall back to the L1 per-op path.");
274	    if (occ < 1) return cudaErrorLaunchOutOfResources;
275	
276	    const unsigned launch_ctas = (unsigned)n_sms;
277	    ctx.n_ctas = launch_ctas;
278	
279	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
280	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
281	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
282	
283	    dim3 grid(launch_ctas), block(256);
284	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
285	        ctx, params, tok, grad, lr, step, st);
286	    return cudaGetLastError();
287	}
288	
289	}}} // namespace sg::fused::sm90
290	
291	#endif  // SG_FUSED_SM90_FUSED_DECODER_MEGAKERNEL_CUH_
