    m.def("gemm_dx",  &gemm_dx,  "TC dX=dY@W (W transposed-staged), bf16/fp32acc");
    m.def("gemm_dw",  &gemm_dw,  "TC dW=dY^T@X (both transposed-staged, K=T), bf16/fp32acc");
    m.attr("TILE_M") = (int)dectc::kTileM;
}

