// ════════════════════════════════════════════════════════════════════════
//  FORWARD over one TOKEN TILE (kTileM rows = nsamp samples × kSeq positions),
//  global token rows [g0, g0+nrows). Tile-batched: the four per-layer linears
//  (in_proj/out_proj/ff0/ff2) run on wgmma (M=nrows, N-tiled), attention/LN/
//  GELU are scalar fp32 over the tile, head/CE are scalar per-sample (M=nsamp<
//  64). Writes the DecActs X-inputs (bf16, the dW operands), the tile scratch
//  (qkv/ff0pre/attn/LN caches for the bwd), and per-sample logits; returns the
//  tile's summed NLL (thread 0 holds it). `tok_ids`/`tgt_ids` are HBM int32.
//
//  DATAFLOW (DecActs regions double as inter-stage bf16 buffers; the fp32
//  intermediates use scratch.tw0/tw1):
//    X_in[li]  := layer input (bf16)          [embedding for li=0]
//    qkv       := X_in @ in_w^T   (scratch, bf16)
//    ctx       := attn(qkv)       (tw0 fp32) → X_ctx[li] (bf16)
//    a         := X_ctx @ out_w^T (tw1 fp32); r1=X_in+a (tw0); n1(r1)→X_x1[li]
//    ff0       := X_x1 @ ff0_w^T  (tw0 fp32) → ff0pre (bf16); gelu→X_gact[li]
//    ff2       := X_gact @ ff2_w^T(tw1 fp32); r2=x1+ff2 (tw0); n2(r2)→X_in[li+1]
//                 (or final_in scratch for the last layer's output)
// ════════════════════════════════════════════════════════════════════════
__device__ float dectc_forward_tile(
        const DecWeights& w, int g0, int nrows, const DecActs& acts,
        const DecTileScratch& sc, const int* __restrict__ tok_ids,
        const int* __restrict__ tgt_ids,
        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
    const int nsamp = nrows / dec::kSeq;
    // ── Embedding: X_in[0][r] = tok[token_id[g0+r]] + pos[(g0+r)%S]. bf16. ──
    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
        const int r = idx / dec::kD, j = idx % dec::kD;
        const int g = g0 + r;
        const int tid = tok_ids[g];
        const int sp = g % dec::kSeq;            // position within the sample
        float v = w.tok[(int64_t)tid * dec::kD + j] + w.pos[(int64_t)sp * dec::kD + j];
        acts.X_in[0][(int64_t)g * dec::kD + j] = __float2bfloat16(v);
    }
    __syncthreads();

    for (int li = 0; li < dec::kLayers; ++li) {
        const DecWeights::Layer& L = w.layer[li];
        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
        // qkv = Xin @ in_w^T   (N=3d, K=d). bf16 → scratch.qkv.
        dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, w_in_w_bf16(L), sc.qkv, dec::kD, 3 * dec::kD, sA, sB);
        __syncthreads();
        // attention → ctx (tw0 fp32) + attn weights.
        dectc_attn_fwd_tile(sc.qkv, nrows, sc.tw0, sc.attn);
        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
            const int r = idx / dec::kD, j = idx % dec::kD;
            acts.X_ctx[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.tw0[(int64_t)r * dec::kD + j]);
        }
        __syncthreads();
        // a = X_ctx @ out_w^T  (N=d, K=d). fp32 → tw1.
        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * dec::kD, w_out_w_bf16(L),
                                            sc.tw1, dec::kD, dec::kD, sA, sB);
        __syncthreads();
        // r1 = Xin + a → tw0 (fp32).
        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
            const int r = idx / dec::kD, j = idx % dec::kD;
            sc.tw0[(int64_t)r * dec::kD + j] = __bfloat162float(Xin[(int64_t)r * dec::kD + j]) + sc.tw1[(int64_t)r * dec::kD + j];
        }
        __syncthreads();
        // n1(r1) → x1 (tw1 fp32) + caches; then bf16 → X_x1[li] (ff0 input + dW operand).
        dectc_ln_fwd_tile(sc.tw0, L.n1_w, L.n1_b, nrows, sc.tw1, sc.n1x, sc.n1i, red);
        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
            const int r = idx / dec::kD, j = idx % dec::kD;
            acts.X_x1[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.tw1[(int64_t)r * dec::kD + j]);
        }
        __syncthreads();
        // ff0 = X_x1 @ ff0_w^T  (N=dff, K=d). fp32 → tw0; pre-gelu bf16 → ff0pre.
        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_x1[li] + (int64_t)g0 * dec::kD, w_ff0_w_bf16(L),
                                            sc.tw0, dec::kD, dec::kDff, sA, sB);
        __syncthreads();
        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
            const int r = idx / dec::kDff, j = idx % dec::kDff;
            float pre = sc.tw0[(int64_t)r * dec::kDff + j];
            sc.ff0pre[(int64_t)r * dec::kDff + j] = __float2bfloat16(pre);
            acts.X_gact[li][(int64_t)(g0 + r) * dec::kDff + j] = __float2bfloat16(dec_gelu(pre));
        }
        __syncthreads();
        // ff2 = X_gact @ ff2_w^T (N=d, K=dff). fp32 → tw1.
        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_gact[li] + (int64_t)g0 * dec::kDff, w_ff2_w_bf16(L),
                                            sc.tw1, dec::kDff, dec::kD, sA, sB);
        __syncthreads();
        // r2 = x1 + ff2 → tw0 (fp32). x1 was overwritten in X_x1 (bf16) — read it back.
        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
            const int r = idx / dec::kD, j = idx % dec::kD;
            float x1 = __bfloat162float(acts.X_x1[li][(int64_t)(g0 + r) * dec::kD + j]);
            sc.tw0[(int64_t)r * dec::kD + j] = x1 + sc.tw1[(int64_t)r * dec::kD + j];
        }
        __syncthreads();
        // n2(r2) → next layer's X_in (bf16), or the last-layer output into X_in[last]+? We
        // store the last layer's n2 output into acts.dh0's slot? No — keep it simple: write
        // into the NEXT layer's X_in if any, else into tw1 (fp32, used right below for head).
        if (li + 1 < dec::kLayers) {
            // n2 → tw1 (fp32) + n2 caches; bf16 → X_in[li+1].
            dectc_ln_fwd_tile(sc.tw0, L.n2_w, L.n2_b, nrows, sc.tw1, sc.n2x, sc.n2i, red);
            for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
                const int r = idx / dec::kD, j = idx % dec::kD;
                acts.X_in[li + 1][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.tw1[(int64_t)r * dec::kD + j]);
            }
            __syncthreads();
        } else {
            // last layer: n2 → tw1 (fp32 "final_in", all positions) + n2 caches.
            dectc_ln_fwd_tile(sc.tw0, L.n2_w, L.n2_b, nrows, sc.tw1, sc.n2x, sc.n2i, red);
            // tw1 now holds final_in [nrows,d] fp32.
        }
    }

    // ── Final norm + head + CE, scalar PER-SAMPLE on the LAST position only.
    //    tw1 holds final_in [nrows,d] fp32. For each sample si the last row is
    //    rbase+S-1. Compute hn = norm(final_last); logits; NLL; cache fn_xhat
    //    (last row) + fn_inv, store X_hn (head dW operand) + logits (bwd). ──
    float nll_acc = 0.0f;
    for (int si = 0; si < nsamp; ++si) {
        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
        const int g = g0 + rlast;
        const float* hlast = sc.tw1 + (int64_t)rlast * dec::kD;
        // LayerNorm of a single row (cooperative).
        float sum = 0.0f;
        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += hlast[j];
        float mean = dec_block_sum(sum, red) / (float)dec::kD;
        float vs = 0.0f;
        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) { float c = hlast[j] - mean; vs += c * c; }
        float var = dec_block_sum(vs, red) / (float)dec::kD;
        float iv = rsqrtf(var + dec::kLnEps);
        if (threadIdx.x == 0) sc.fni[rlast] = iv;
        // hn into tw0 row rlast (fp32 scratch); fn_xhat cache; X_hn bf16.
        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
            float xh = (hlast[j] - mean) * iv;
            sc.fnx[(int64_t)rlast * dec::kD + j] = xh;
            float hn = xh * w.norm_w[j] + w.norm_b[j];
            sc.tw0[(int64_t)rlast * dec::kD + j] = hn;
            acts.X_hn[(int64_t)si_global(g0, si) * dec::kD + j] = __float2bfloat16(hn);
        }
        __syncthreads();
        // logits[o] = hn · out_w[o] + out_b[o]   (scalar, o over V). Store dlogits
        // operand later; here compute logits into a per-sample slot in tw1 row 0..? We
        // need V=99 logits per sample; stash in dsc-adjacent? Reuse the head dW operand
        // path: write logits into acts.dY_logits temporarily as fp32-in-bf16? Keep
        // logits in a small register-free path: write into sc.dsc as fp32 [V] per sample.
        float* lg = sc.dsc + (int64_t)si * dec::kVocab;   // dsc is large enough (nSamp*H*S*S >= nSamp*V? check)
        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
            const float* Wr = w.out_w + (int64_t)o * dec::kD;
            float acc = w.out_b[o];
            const float* hn = sc.tw0 + (int64_t)rlast * dec::kD;
            #pragma unroll 4
            for (int k = 0; k < dec::kD; ++k) acc += hn[k] * Wr[k];
            lg[o] = acc;
        }
        __syncthreads();
        // NLL = logz - logits[target].
        int tgt = tgt_ids[si_global(g0, si)];
        float lmax = -CUDART_INF_F;
        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
        lmax = dec_block_max(lmax, red);
        float es = 0.0f;
        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
        es = dec_block_sum(es, red);
        float logz = lmax + __logf(es);
        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
        __syncthreads();
    }
    return nll_acc;
}

}  // namespace dectc

