351	// ════════════════════════════════════════════════════════════════════════
352	//  Per-CTA TILE SCRATCH (HBM). One tile's forward intermediates the backward
353	//  reads, reused across the tiles a CTA grid-strides over (a CTA finishes a
354	//  tile's fwd+bwd before the next tile, so one slab per CTA suffices). Sized
355	//  for kTileM rows. The X-inputs / dY-adjoints that OTHER CTAs read in P2's dW
356	//  do NOT live here — they live in the full-T DecActs (cross-CTA). This holds
357	//  only the within-tile fwd state (qkv for attn-bwd, pre-gelu for gelu', the
358	//  LN caches, the running adjoint) so the backward needs NO recompute.
359	//
360	//  Layout (per CTA), row-major [rows × width]:
361	//    qkv     [kTileM, 3d]   bf16   in_proj output (q|k|v for attention bwd)
362	//    ff0pre  [kTileM, dff]  bf16   pre-GELU FFN hidden (gelu' needs it)
363	//    attn    [nSamp, H, S, S] f32  softmax weights (attention bwd)
364	//    n1x/n2x/fnx [kTileM, d] f32   LN xhat caches (LN bwd)
365	//    n1i/n2i/fni [kTileM]    f32   LN inv-std caches
366	//    dh      [kTileM, d]     f32   running adjoint wrt block output
367	//    dsc     [nSamp, H, S, S] f32  attention dscores scratch
368	//  nSamp = kTileM/S samples per tile.
369	// ════════════════════════════════════════════════════════════════════════
370	struct DecTileScratch {
371	    __nv_bfloat16* qkv;     // [kTileM, 3d]
372	    __nv_bfloat16* ff0pre;  // [kTileM, dff]
373	    float* attn;            // [nSamp*H*S*S]
374	    float* n1x; float* n1i;
375	    float* n2x; float* n2i;
376	    float* fnx; float* fni;
377	    float* dh;              // [kTileM, d]
378	    float* dsc;             // [nSamp*H*S*S]
379	    // fp32 tile-working buffers (reused across stages; max width dff):
380	    float* tw0;             // [kTileM, dff]   GEMM-output / general scratch
381	    float* tw1;             // [kTileM, dff]   residual base / second operand
382	};
383	
384	// nSamp samples per tile, H*S*S attention entries each.
385	constexpr int kAttnPerTile = (kTileM / dec::kSeq) * dec::kHeads * dec::kSeq * dec::kSeq;
386	
387	// Bytes one CTA's scratch occupies (for host sizing of the workspace tail).
388	__host__ __device__ __forceinline__ int64_t dec_tile_scratch_bf16_count() {
389	    return (int64_t)kTileM * 3 * dec::kD + (int64_t)kTileM * dec::kDff;  // qkv + ff0pre
390	}
391	__host__ __device__ __forceinline__ int64_t dec_tile_scratch_f32_count() {
392	    return (int64_t)kAttnPerTile                         // attn
393	         + 3 * ((int64_t)kTileM * dec::kD + kTileM)      // n1/n2/fn xhat+inv
394	         + (int64_t)kTileM * dec::kD                     // dh
395	         + (int64_t)kAttnPerTile                         // dsc
396	         + 2 * (int64_t)kTileM * dec::kDff;              // tw0 + tw1
397	}
