399	// Bind a CTA's scratch from a per-CTA float slab. bf16 regions are packed at the
400	// FRONT (reinterpreted), fp32 regions after. `slab` is float* (the caller gives
401	// each CTA dec_tile_scratch_total_f32() floats).
402	__host__ __device__ __forceinline__ int64_t dec_tile_scratch_total_f32() {
403	    // bf16 count rounded up to whole floats + f32 count.
404	    return (dec_tile_scratch_bf16_count() + 1) / 2 + dec_tile_scratch_f32_count();
405	}
406	
407	__device__ __forceinline__ DecTileScratch dec_tile_scratch_bind(float* slab) {
408	    DecTileScratch s;
409	    __nv_bfloat16* b = reinterpret_cast<__nv_bfloat16*>(slab);
410	    int64_t bo = 0;
411	    s.qkv    = b + bo; bo += (int64_t)kTileM * 3 * dec::kD;
412	    s.ff0pre = b + bo; bo += (int64_t)kTileM * dec::kDff;
413	    float* f = slab + (dec_tile_scratch_bf16_count() + 1) / 2;
414	    int64_t fo = 0;
415	    s.attn = f + fo; fo += kAttnPerTile;
