// ════════════════════════════════════════════════════════════════════════
//  Per-CTA TILE SCRATCH (HBM). One tile's forward intermediates the backward
//  reads, reused across the tiles a CTA grid-strides over (a CTA finishes a
//  tile's fwd+bwd before the next tile, so one slab per CTA suffices). Sized
//  for kTileM rows. The X-inputs / dY-adjoints that OTHER CTAs read in P2's dW
//  do NOT live here — they live in the full-T DecActs (cross-CTA). This holds
//  only the within-tile fwd state (qkv for attn-bwd, pre-gelu for gelu', the
//  LN caches, the running adjoint) so the backward needs NO recompute.
//
//  Layout (per CTA), row-major [rows × width]:
//    qkv     [kTileM, 3d]   bf16   in_proj output (q|k|v for attention bwd)
//    ff0pre  [kTileM, dff]  bf16   pre-GELU FFN hidden (gelu' needs it)
//    attn    [nSamp, H, S, S] f32  softmax weights (attention bwd)
//    n1x/n2x/fnx [kTileM, d] f32   LN xhat caches (LN bwd)
//    n1i/n2i/fni [kTileM]    f32   LN inv-std caches
//    dh      [kTileM, d]     f32   running adjoint wrt block output
//    dsc     [nSamp, H, S, S] f32  attention dscores scratch
//  nSamp = kTileM/S samples per tile.
// ════════════════════════════════════════════════════════════════════════
struct DecTileScratch {
    __nv_bfloat16* qkv;     // [kTileM, 3d]
    __nv_bfloat16* ff0pre;  // [kTileM, dff]
    float* attn;            // [nSamp*H*S*S]
    float* n1x; float* n1i;
    float* n2x; float* n2i;
    float* fnx; float* fni;
    float* dh;              // [kTileM, d]
    float* dsc;             // [nSamp*H*S*S]
    // fp32 tile-working buffers (reused across stages; max width dff):
    float* tw0;             // [kTileM, dff]   GEMM-output / general scratch
    float* tw1;             // [kTileM, dff]   residual base / second operand
};

// nSamp samples per tile, H*S*S attention entries each.
constexpr int kAttnPerTile = (kTileM / dec::kSeq) * dec::kHeads * dec::kSeq * dec::kSeq;

// Bytes one CTA's scratch occupies (for host sizing of the workspace tail).
__host__ __device__ __forceinline__ int64_t dec_tile_scratch_bf16_count() {
    return (int64_t)kTileM * 3 * dec::kD + (int64_t)kTileM * dec::kDff;  // qkv + ff0pre
}
__host__ __device__ __forceinline__ int64_t dec_tile_scratch_f32_count() {
    return (int64_t)kAttnPerTile                         // attn
         + 3 * ((int64_t)kTileM * dec::kD + kTileM)      // n1/n2/fn xhat+inv
         + (int64_t)kTileM * dec::kD                     // dh
         + (int64_t)kAttnPerTile                         // dsc
         + 2 * (int64_t)kTileM * dec::kDff;              // tw0 + tw1
}

// Bind a CTA's scratch from a per-CTA float slab. bf16 regions are packed at the
// FRONT (reinterpreted), fp32 regions after. `slab` is float* (the caller gives
// each CTA dec_tile_scratch_total_f32() floats).
__host__ __device__ __forceinline__ int64_t dec_tile_scratch_total_f32() {
    // bf16 count rounded up to whole floats + f32 count.
    return (dec_tile_scratch_bf16_count() + 1) / 2 + dec_tile_scratch_f32_count();
}

__device__ __forceinline__ DecTileScratch dec_tile_scratch_bind(float* slab) {
    DecTileScratch s;
    __nv_bfloat16* b = reinterpret_cast<__nv_bfloat16*>(slab);
    int64_t bo = 0;
    s.qkv    = b + bo; bo += (int64_t)kTileM * 3 * dec::kD;
    s.ff0pre = b + bo; bo += (int64_t)kTileM * dec::kDff;
    float* f = slab + (dec_tile_scratch_bf16_count() + 1) / 2;
    int64_t fo = 0;
    s.attn = f + fo; fo += kAttnPerTile;
    s.n1x  = f + fo; fo += (int64_t)kTileM * dec::kD;
    s.n1i  = f + fo; fo += kTileM;
    s.n2x  = f + fo; fo += (int64_t)kTileM * dec::kD;
    s.n2i  = f + fo; fo += kTileM;
    s.fnx  = f + fo; fo += (int64_t)kTileM * dec::kD;
    s.fni  = f + fo; fo += kTileM;
    s.dh   = f + fo; fo += (int64_t)kTileM * dec::kD;
    s.dsc  = f + fo; fo += kAttnPerTile;
    s.tw0  = f + fo; fo += (int64_t)kTileM * dec::kDff;
    s.tw1  = f + fo; fo += (int64_t)kTileM * dec::kDff;
    return s;
}

