        float iv = rsqrtf(var + dec::kLnEps);
        if (threadIdx.x == 0) sc.fni[rlast] = iv;
        // hn into tw0 row rlast (fp32 scratch); fn_xhat cache; X_hn bf16.
        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
            float xh = (hlast[j] - mean) * iv;
            sc.fnx[(int64_t)rlast * dec::kD + j] = xh;
            float hn = xh * w.norm_w[j] + w.norm_b[j];
            sc.tw0[(int64_t)rlast * dec::kD + j] = hn;
            acts.X_hn[(int64_t)si_global(g0, si) * dec::kD + j] = __float2bfloat16(hn);
        }
        __syncthreads();
        // logits[o] = hn · out_w[o] + out_b[o]   (scalar, o over V). Store dlogits
        // operand later; here compute logits into a per-sample slot in tw1 row 0..? We
        // need V=99 logits per sample; stash in dsc-adjacent? Reuse the head dW operand
        // path: write logits into acts.dY_logits temporarily as fp32-in-bf16? Keep
        // logits in a small register-free path: write into sc.dsc as fp32 [V] per sample.
        float* lg = sc.dsc + (int64_t)si * dec::kVocab;   // dsc is large enough (nSamp*H*S*S >= nSamp*V? check)
        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
            const float* Wr = w.out_w + (int64_t)o * dec::kD;
            float acc = w.out_b[o];
            const float* hn = sc.tw0 + (int64_t)rlast * dec::kD;
            #pragma unroll 4
            for (int k = 0; k < dec::kD; ++k) acc += hn[k] * Wr[k];
            lg[o] = acc;
        }
        __syncthreads();
        // NLL = logz - logits[target].
        int tgt = tgt_ids[si_global(g0, si)];
        float lmax = -CUDART_INF_F;
        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
        lmax = dec_block_max(lmax, red);
        float es = 0.0f;
        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
        es = dec_block_sum(es, red);
        float logz = lmax + __logf(es);
        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
        __syncthreads();
    }
    return nll_acc;
}

